DROP TABLE IF EXISTS `candidatos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `candidatos` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(80) NOT NULL,
  `nome` varchar(120) NOT NULL,
  `nome_completo` varchar(180) DEFAULT NULL,
  `partido` varchar(20) NOT NULL,
  `numero` smallint(5) unsigned NOT NULL,
  `cargo` varchar(30) NOT NULL DEFAULT 'presidente',
  `uf` varchar(2) NOT NULL DEFAULT 'BR',
  `foto_url_original` text DEFAULT NULL,
  `foto_local` varchar(255) DEFAULT NULL,
  `perfil_g1_url` text DEFAULT NULL,
  `profissao` varchar(120) DEFAULT NULL,
  `genero` varchar(20) DEFAULT NULL,
  `cor_etnia` varchar(30) DEFAULT NULL,
  `grau_instrucao` varchar(80) DEFAULT NULL,
  `plano_governo_url` text DEFAULT NULL,
  `vice_nome` varchar(120) DEFAULT NULL,
  `vice_partido` varchar(20) DEFAULT NULL,
  `patrimonio_total` decimal(15,2) DEFAULT NULL,
  `receitas_total` decimal(15,2) DEFAULT NULL,
  `despesas_total` decimal(15,2) DEFAULT NULL,
  `limite_gastos` decimal(15,2) DEFAULT NULL,
  `coletado_em` datetime DEFAULT NULL,
  `fonte_atualizado_em` varchar(60) DEFAULT NULL,
  `raw_json` mediumtext DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `cargo_uf_slug` (`cargo`,`uf`,`slug`),
  KEY `partido` (`partido`),
  KEY `cargo` (`cargo`),
  KEY `cargo_numero` (`cargo`,`numero`)
) ENGINE=InnoDB AUTO_INCREMENT=206 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
