--
-- Table structure for table `candidatos_tse`
--

DROP TABLE IF EXISTS `candidatos_tse`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `candidatos_tse` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `candidato_id` int(10) unsigned NOT NULL,
  `sq_candidato` varchar(30) DEFAULT NULL,
  `tse_documento_id` varchar(50) DEFAULT NULL,
  `cnpj_campanha` varchar(20) DEFAULT NULL,
  `situacao_registro` varchar(60) NOT NULL DEFAULT 'Deferido',
  `processo_pje` varchar(60) DEFAULT NULL,
  `limite_gastos_1t` decimal(15,2) DEFAULT NULL,
  `limite_gastos_2t` decimal(15,2) DEFAULT NULL,
  `patrimonio_declarado` decimal(15,2) DEFAULT NULL,
  `soma_bens_calculada` decimal(15,2) DEFAULT NULL,
  `divergencia_bens` decimal(15,2) NOT NULL DEFAULT 0.00,
  `bens_consistentes` tinyint(1) NOT NULL DEFAULT 1,
  `receitas_total` decimal(15,2) DEFAULT NULL,
  `despesas_total` decimal(15,2) DEFAULT NULL,
  `saldo_campanha` decimal(15,2) DEFAULT NULL,
  `situacao_caixa` varchar(40) NOT NULL DEFAULT 'SUPERAVIT_OU_NEUTRO',
  `dentro_limite_tse` tinyint(1) NOT NULL DEFAULT 1,
  `percentual_gasto_teto` decimal(6,2) DEFAULT NULL,
  `total_bens` int(10) unsigned NOT NULL DEFAULT 0,
  `total_doadores` int(10) unsigned NOT NULL DEFAULT 0,
  `total_fornecedores` int(10) unsigned NOT NULL DEFAULT 0,
  `status_geral` varchar(30) NOT NULL DEFAULT 'CONFORME',
  `validado_em` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `candidato_id` (`candidato_id`),
  KEY `sq_candidato` (`sq_candidato`),
  KEY `status_geral` (`status_geral`),
  CONSTRAINT `candidatos_tse_candidato_id_foreign` FOREIGN KEY (`candidato_id`) REFERENCES `candidatos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

